def main() -> None:
    PORTALS_DIR.mkdir(parents=True, exist_ok=True)
    WALLS_DIR.mkdir(parents=True, exist_ok=True)
    manifest_entries: list[dict] = []

    print(f"=== GENERATING {len(NEW_PORTALS)} BRAND-NEW UNIQUE PORTALS ===")
    p_qa: list[tuple[str, Image.Image]] = []
    for idx, (slug, disp, tags, spec) in enumerate(NEW_PORTALS):
        s = dict(spec)
        s.setdefault("seed", 2000 + idx * 17)
        im = render_portal(s)
        out_p = PORTALS_DIR / f"{slug}.png"
        im.save(out_p, "PNG", optimize=True)
        is_col = bool(s.get("colorable", False)) or slug.startswith(("door_colorable", "win_colorable", "curtain_colorable", "gate_colorable"))
        manifest_entries.append({
            "path": f"portals/harmony/{slug}.png",
            "displayName": disp,
            "category": "portal",
            "tags": tags,
            "widthPx": im.width,
            "heightPx": im.height,
            "defaultPpi": 256,
            "drawMode": "colorable" if is_col else "normal",
            "castsShadow": True,
            "dominantHex": dominant_hex(im),
        })
        p_qa.append((slug, im))
    save_qa_sheet(p_qa[:56], SCRATCH_DIR / "qa_new_portals_part1.png", cols=7, cw=215, ch=115)
    save_qa_sheet(p_qa[56:], SCRATCH_DIR / "qa_new_portals_part2.png", cols=7, cw=215, ch=115)

    print(f"=== GENERATING {len(NEW_WALLS)} BRAND-NEW UNIQUE WALLS ===")
    w_qa: list[tuple[str, Image.Image]] = []
    for idx, (slug, disp, tags, spec) in enumerate(NEW_WALLS):
        s = dict(spec)
        s.setdefault("seed", 4000 + idx * 19)
        im = render_wall(s)
        out_p = WALLS_DIR / f"{slug}.png"
        im.save(out_p, "PNG", optimize=True)
        is_col = bool(s.get("colorable", False)) or slug.startswith("wall_col_")
        manifest_entries.append({
            "path": f"walls/harmony/{slug}.png",
            "displayName": disp,
            "category": "wall",
            "tags": tags,
            "widthPx": im.width,
            "heightPx": im.height,
            "defaultPpi": 256,
            "drawMode": "colorable" if is_col else "normal",
            "castsShadow": True,
            "dominantHex": dominant_hex(im),
        })
        w_qa.append((slug, im))
    save_qa_sheet(w_qa[:55], SCRATCH_DIR / "qa_new_walls_part1.png", cols=5, cw=280, ch=88)
    save_qa_sheet(w_qa[55:], SCRATCH_DIR / "qa_new_walls_part2.png", cols=5, cw=280, ch=88)

    total = upsert_manifest_entries(MOD_DIR / "manifest.json", manifest_entries)
    print(f"DONE Step 4: Created {len(NEW_PORTALS)} new portals + {len(NEW_WALLS)} new walls ({len(manifest_entries)} total). modular-suite manifest -> {total} assets!")


if __name__ == "__main__":
    main()
